        } else if arg == "-t" || arg == "--types" {
            i += 1;
            if i < args.len() {
                for t in args[i].split(',') {
                    cli.types.push(t.trim().to_string());
                }
            }
        } else if arg.starts_with("-t=") || arg.starts_with("--types=") {
