}

#[derive(Debug, Default)]
struct Cli {
    inputs: Vec<PathBuf>,
    columns: Option<usize>,
    exclude: Vec<String>,
    files: bool,
    input_file: Option<String>,
    hidden: bool,
    languages: bool,
    no_ignore: bool,
