    no_ignore_dot: bool,
    no_ignore_vcs: bool,
    output: Option<String>,
    streaming: Option<String>,
    sort: Option<String>,
    rsort: Option<String>,
    types: Vec<String>,
    compact: bool,
    num_format: Option<String>,
    verbose: u8,
    help: bool,
    version: bool,
}

fn parse_args() -> Cli {
    let args: Vec<String> = env::args().collect();
    let mut cli = Cli::default();
    let mut i = 1;

    while i < args.len() {
        let arg = &args[i];
        if arg == "-h" || arg == "--help" {
            cli.help = true;
        } else if arg == "-V" || arg == "--version" {
            cli.version = true;
        } else if arg == "-f" || arg == "--files" {
            cli.files = true;
        } else if arg == "--hidden" {
            cli.hidden = true;
        } else if arg == "-l" || arg == "--languages" {
            cli.languages = true;
        } else if arg == "--no-ignore" {
            cli.no_ignore = true;
        } else if arg == "--no-ignore-parent" {
            cli.no_ignore_parent = true;
        } else if arg == "--no-ignore-dot" {
            cli.no_ignore_dot = true;
        } else if arg == "--no-ignore-vcs" {
            cli.no_ignore_vcs = true;
        } else if arg == "-C" || arg == "--compact" {
            cli.compact = true;
        } else if arg.starts_with("-v") && arg.chars().skip(1).all(|c| c == 'v') {
            cli.verbose = (arg.len() - 1) as u8;
        } else if arg == "-c" || arg == "--columns" {
            i += 1;
            if i < args.len() {
                cli.columns = args[i].parse().ok();
            }
        } else if arg.starts_with("--columns=") {
            cli.columns = arg["--columns=".len()..].parse().ok();
        } else if arg == "-e" || arg == "--exclude" {
            i += 1;
            if i < args.len() {
                cli.exclude.push(args[i].clone());
            }
        } else if arg.starts_with("--exclude=") {
            cli.exclude.push(arg["--exclude=".len()..].to_string());
        } else if arg == "-i" || arg == "--input" {
            i += 1;
            if i < args.len() {
                cli.input_file = Some(args[i].clone());
            }
        } else if arg.starts_with("--input=") {
            cli.input_file = Some(arg["--input=".len()..].to_string());
        } else if arg == "-o" || arg == "--output" {
            i += 1;
            if i < args.len() {
                cli.output = Some(args[i].clone());
            }
        } else if arg.starts_with("--output=") {
            cli.output = Some(arg["--output=".len()..].to_string());
        } else if arg == "--streaming" {
            i += 1;
            if i < args.len() {
                cli.streaming = Some(args[i].clone());
            }
        } else if arg.starts_with("--streaming=") {
            cli.streaming = Some(arg["--streaming=".len()..].to_string());
        } else if arg == "-s" || arg == "--sort" {
            i += 1;
            if i < args.len() {
                cli.sort = Some(args[i].clone());
            }
        } else if arg.starts_with("--sort=") {
            cli.sort = Some(arg["--sort=".len()..].to_string());
        } else if arg == "-r" || arg == "--rsort" {
            i += 1;
            if i < args.len() {
                cli.rsort = Some(args[i].clone());
            }
        } else if arg.starts_with("--rsort=") {
            cli.rsort = Some(arg["--rsort=".len()..].to_string());
        } else if arg == "-t" || arg == "--types" {
            i += 1;
            if i < args.len() {
                for t in args[i].split(',') {
                    cli.types.push(t.trim().to_string());
                }
            }
        } else if arg.starts_with("-t=") || arg.starts_with("--types=") {
            let val = if arg.starts_with("-t=") { &arg[3..] } else { &arg["--types=".len()..] };
            for t in val.split(',') {
                cli.types.push(t.trim().to_string());
            }
        } else if arg == "-n" || arg == "--num-format" {
            i += 1;
            if i < args.len() {
                cli.num_format = Some(args[i].clone());
            }
        } else if arg.starts_with("--num-format=") {
            cli.num_format = Some(arg["--num-format=".len()..].to_string());
        } else if !arg.starts_with('-') {
            cli.inputs.push(PathBuf::from(arg));
        }
        i += 1;
    }

    cli
}

