    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            ws.ws_col as usize
        } else {
            80
        }
    }
}

fn find_lang_by_path(path: &Path) -> Option<&'static LangDef> {
    let filename = path.file_name()?.to_str()?;

    for lang in LANGUAGES {
        for ext in lang.extensions {
            if ext.eq_ignore_ascii_case(filename) {
                return Some(lang);
            }
        }
    }

    if let Some(ext_os) = path.extension() {
        if let Some(ext) = ext_os.to_str() {
            for lang in LANGUAGES {
                for l_ext in lang.extensions {
                    if l_ext.eq_ignore_ascii_case(ext) {
                        return Some(lang);
                    }
                }
            }
        }
    }

    None
}

fn find_lang_by_tag(tag: &str) -> Option<&'static LangDef> {
    if tag.is_empty() {
        return None;
    }
    let tag_lower = tag.to_lowercase();
    for lang in LANGUAGES {
        if lang.name.to_lowercase() == tag_lower || (lang.name == "C++" && tag_lower == "c++") || (lang.name == "C#" && tag_lower == "c#") {
            return Some(lang);
        }
    }
    for lang in LANGUAGES {
        for ext in lang.extensions {
            if ext.to_lowercase() == tag_lower {
                return Some(lang);
            }
        }
    }
    None
}

fn count_file(path: &Path, lang: &'static LangDef) -> (Stat, Option<BTreeMap<String, Stat>>) {
    let content = match fs::read_to_string(path) {
        Ok(c) => c,
        Err(_) => return (Stat::default(), None),
    };

    let mut stat = Stat::default();
    let mut embedded: BTreeMap<String, Stat> = BTreeMap::new();

    if lang.name == "Markdown" {
        let mut in_code_block = false;
        let mut current_block_lang: Option<&'static LangDef> = None;
        let mut block_lines: Vec<String> = Vec::new();

        for line in content.lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
                if in_code_block {
                    if let Some(e_lang) = current_block_lang {
                        let block_text = block_lines.join("\n");
                        let (sub_stat, _) = count_str(&block_text, e_lang);
                        let entry = embedded.entry(e_lang.name.to_string()).or_default();
                        entry.code += sub_stat.code;
                        entry.comments += sub_stat.comments;
                        entry.blanks += sub_stat.blanks;
                    }
                    in_code_block = false;
                    current_block_lang = None;
                    block_lines.clear();
                    stat.comments += 1;
                } else {
                    in_code_block = true;
                    let tag = trimmed.trim_start_matches('`').trim_start_matches('~').trim();
                    current_block_lang = find_lang_by_tag(tag);
                    stat.comments += 1;
                }
            } else if in_code_block {
                block_lines.push(line.to_string());
                stat.comments += 1;
            } else {
                if trimmed.is_empty() {
                    stat.blanks += 1;
                } else {
                    stat.comments += 1;
                }
            }
        }
        stat.blobs = embedded.clone();
        return (stat, if embedded.is_empty() { None } else { Some(embedded) });
    }

    if lang.name == "Rust" {
        let mut doc_lines: Vec<String> = Vec::new();

        for line in content.lines() {
            let trimmed = line.trim();
            if trimmed.starts_with("///") || trimmed.starts_with("//!") {
                let doc_content = if trimmed.len() >= 4 { &trimmed[3..] } else { "" };
                doc_lines.push(doc_content.to_string());
            }
        }

        if !doc_lines.is_empty() {
            let md_lang = find_lang_by_tag("markdown");
            if let Some(md) = md_lang {
                let doc_text = doc_lines.join("\n");
                let (md_stat, md_emb) = count_file_content(&doc_text, md);
                embedded.insert("Markdown".to_string(), md_stat);
                if let Some(emb_map) = md_emb {
                    for (k, v) in emb_map {
                        embedded.insert(k, v);
                    }
                }
            }
        }
    }

    let (s, _) = count_str(&content, lang);
    stat.code = s.code;
    stat.comments = s.comments;
    stat.blanks = s.blanks;
    stat.blobs = embedded.clone();

    (stat, if embedded.is_empty() { None } else { Some(embedded) })
}

