fn count_str(content: &str, lang: &'static LangDef) -> (Stat, Option<BTreeMap<String, Stat>>) {
    let mut stat = Stat::default();
    let mut comment_depth = 0;
    let mut current_multi_end = "";

    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if comment_depth > 0 {
                stat.comments += 1;
            } else {
                stat.blanks += 1;
            }
            continue;
        }

        if comment_depth > 0 {
            stat.comments += 1;
            if trimmed.contains(current_multi_end) {
                if lang.nested {
                    comment_depth -= 1;
                } else {
                    comment_depth = 0;
                }
            }
            continue;
        }

        let mut has_comment = false;

        for sl in lang.line_comments {
            if trimmed.starts_with(sl) {
                has_comment = true;
                break;
            }
        }

        if !has_comment {
            for (ml_start, ml_end) in lang.multi_line_comments {
                if trimmed.starts_with(ml_start) {
                    has_comment = true;
                    if !trimmed.contains(ml_end) || trimmed.find(ml_start) == trimmed.rfind(ml_end) {
                        comment_depth += 1;
                        current_multi_end = ml_end;
                    }
                    break;
                }
            }
        }

        if has_comment {
            stat.comments += 1;
        } else {
            stat.code += 1;
        }
    }

    (stat, None)
}

fn main() {
    let cli = parse_args();

    if cli.help {
        print_help();
        return;
    }

    if cli.version {
        safe_println("tokei 14.0.0 compiled with serialization support: json");
        return;
    }

    if cli.languages {
        print_languages();
        return;
    }

    if cli.num_format.is_some() && cli.output.is_some() {
        eprintln!("error: the argument '--num-format <num_format_style>' cannot be used with '--output <output>'\n\nUsage: executable --num-format <num_format_style> <input>...\n\nFor more information, try '--help'.");
        process::exit(2);
    }

    if let Some(ref out_fmt) = cli.output {
        if out_fmt != "json" {
            eprintln!("error: invalid value '{}' for '--output <output>': This version of tokei was compiled without any '{}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n\n\nFor more information, try '--help'.", out_fmt, out_fmt, out_fmt);
            process::exit(2);
        }
    }

    let inputs = if cli.inputs.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        cli.inputs.clone()
    };

    for input in &inputs {
        if !input.exists() {
            eprintln!("Error: '{}' not found.", input.display());
            process::exit(1);
        }
    }

    let mut languages_map: BTreeMap<String, Language> = BTreeMap::new();

    if let Some(ref input_file_path) = cli.input_file {
        let json_str = if input_file_path == "stdin" {
            let mut s = String::new();
            io::stdin().read_to_string(&mut s).ok();
            s
        } else {
            fs::read_to_string(input_file_path).unwrap_or_default()
        };

        if let Ok(deserialized) = serde_json::from_str::<BTreeMap<String, Language>>(&json_str) {
            for (k, v) in deserialized {
                if k != "Total" {
                    languages_map.insert(k, v);
                }
            }
        } else {
            eprintln!("Error:\n Failed to parse input file: {}\n\nThis version of tokei was compiled without serialization support for the following formats:\n\n    cbor, json, yaml\n\nYou may want to install any comma separated combination of \"cbor,json,yaml\":\n\n    cargo install tokei --features \"cbor,json,yaml\"\n\nOr use the 'all' feature:\n\n    cargo install tokei --features all\n    \n", input_file_path);
            process::exit(1);
        }
    }

    let mut builder = WalkBuilder::new(&inputs[0]);
    for input in inputs.iter().skip(1) {
        builder.add(input);
    }

    builder.hidden(!cli.hidden);
    builder.git_ignore(!cli.no_ignore && !cli.no_ignore_vcs);
    builder.git_exclude(!cli.no_ignore && !cli.no_ignore_vcs);
    builder.git_global(!cli.no_ignore && !cli.no_ignore_vcs);
    builder.ignore(!cli.no_ignore && !cli.no_ignore_dot);
    builder.parents(!cli.no_ignore_parent);

    let walker = builder.build();

    for result in walker {
        let entry = match result {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();
        if !path.is_file() {
            continue;
        }

        if !cli.exclude.is_empty() {
            let path_str = path.to_string_lossy();
            let mut excluded = false;
            for pattern in &cli.exclude {
                if path_str.contains(pattern) || path.file_name().and_then(|n| n.to_str()).map_or(false, |name| name == pattern) {
                    excluded = true;
                    break;
                }
            }
            if excluded {
                continue;
            }
        }

        if let Some(lang) = find_lang_by_path(path) {
            let (stat, embedded) = count_file(path, lang);

            let lang_entry = languages_map.entry(lang.name.to_string()).or_default();
            lang_entry.code += stat.code;
            lang_entry.comments += stat.comments;
            lang_entry.blanks += stat.blanks;

            let report = Report {
                stats: stat.clone(),
                name: path.to_path_buf(),
            };
            lang_entry.reports.push(report.clone());

            if let Some(emb) = embedded {
                for (emb_lang, emb_stat) in emb {
                    let emb_reports = lang_entry.children.entry(emb_lang.clone()).or_default();
                    emb_reports.push(Report {
                        stats: emb_stat,
                        name: path.to_path_buf(),
                    });
                }
            }
        }
    }

    let mut total_lang = Language::default();
    let mut total_children: BTreeMap<String, Vec<Report>> = BTreeMap::new();

    for (lang_name, lang_data) in &languages_map {
        total_lang.code += lang_data.code;
        total_lang.comments += lang_data.comments;
        total_lang.blanks += lang_data.blanks;

        for child_reports in lang_data.children.values() {
            for r in child_reports {
                total_lang.code += r.stats.code;
                total_lang.comments += r.stats.comments;
                total_lang.blanks += r.stats.blanks;
            }
        }

        total_children.insert(lang_name.clone(), lang_data.reports.clone());
    }

    total_lang.children = total_children;

    if cli.output.as_deref() == Some("json") {
        let mut final_map: BTreeMap<String, Language> = languages_map.clone();
        final_map.insert("Total".to_string(), total_lang);
        safe_println(&serde_json::to_string(&final_map).unwrap());
        return;
    }

    if cli.streaming.is_some() {
        if cli.streaming.as_deref() == Some("simple") {
            safe_println("# language                                        path                                          lines         code       comments      blanks   ");
            safe_println("########## ################################################################################ ############ ############ ############ ############");
            for (lang_name, lang_data) in &languages_map {
                for report in &lang_data.reports {
                    let lines = report.stats.code + report.stats.comments + report.stats.blanks;
                    safe_println(&format!("{:>10} {:<80} {:>12} {:>12} {:>12} {:>12}", lang_name, report.name.display(), lines, report.stats.code, report.stats.comments, report.stats.blanks));
                }
            }
        } else if cli.streaming.as_deref() == Some("json") {
            for (lang_name, lang_data) in &languages_map {
                for report in &lang_data.reports {
                    let obj = serde_json::json!({
                        "language": lang_name,
                        "stats": {
                            "name": report.name,
                            "stats": {
                                "blanks": report.stats.blanks,
                                "blobs": report.stats.blobs,
                                "code": report.stats.code,
                                "comments": report.stats.comments
                            }
                        }
                    });
                    safe_println(&serde_json::to_string(&obj).unwrap());
                }
            }
        }
        return;
    }

    let term_width = get_term_width(cli.columns);
    let b_len = if term_width <= 81 { 81 } else { term_width };
    let h_len = b_len - 1;

    let border_heavy = "━".repeat(b_len);
    let border_light = "─".repeat(b_len);

    safe_println(&border_heavy);

    let lang_col_w = h_len - 58;
    let header_line = format!(" {:<w$}{:>12}{:>13}{:>13}{:>13}{:>7}", 
        "Language", "Files", "Lines", "Code", "Comments", "Blanks", 
        w = lang_col_w - 1);
    safe_println(&header_line);

    safe_println(&border_heavy);

    let type_set: Option<HashSet<String>> = if cli.types.is_empty() {
        None
    } else {
        Some(cli.types.iter().map(|t| t.to_lowercase()).collect())
    };

    let mut sorted_keys: Vec<String> = languages_map.keys().cloned().collect();

    if let Some(ref filter_types) = type_set {
        sorted_keys.retain(|k| filter_types.contains(&k.to_lowercase()));
    }

    if let Some(ref sort_col) = cli.sort {
        sorted_keys.sort_by(|a, b| {
            let la = &languages_map[a];
            let lb = &languages_map[b];
            let va = get_col_val(la, sort_col);
            let vb = get_col_val(lb, sort_col);
            vb.cmp(&va)
        });
    } else if let Some(ref rsort_col) = cli.rsort {
        sorted_keys.sort_by(|a, b| {
            let la = &languages_map[a];
            let lb = &languages_map[b];
            let va = get_col_val(la, rsort_col);
            let vb = get_col_val(lb, rsort_col);
            va.cmp(&vb)
        });
    }

    let mut printed_langs = 0;

    for key in &sorted_keys {
        let lang = &languages_map[key];
        let total_lines = lang.code + lang.comments + lang.blanks;

        if total_lines == 0 && lang.reports.is_empty() {
            continue;
        }

        if printed_langs > 0 {
            safe_println(&border_light);
        }

        printed_langs += 1;

        let line_str = format!(" {:<w$}{:>12}{:>13}{:>13}{:>13}{:>7}",
            key,
            format_num(lang.reports.len(), &cli.num_format),
            format_num(total_lines, &cli.num_format),
            format_num(lang.code, &cli.num_format),
            format_num(lang.comments, &cli.num_format),
            format_num(lang.blanks, &cli.num_format),
            w = lang_col_w - 1
        );
        safe_println(&line_str);

        if !cli.compact && !lang.children.is_empty() {
            for (child_name, child_reports) in &lang.children {
                let mut c_code = 0;
                let mut c_comments = 0;
                let mut c_blanks = 0;
                for r in child_reports {
                    c_code += r.stats.code;
                    c_comments += r.stats.comments;
                    c_blanks += r.stats.blanks;
                }
                let c_lines = c_code + c_comments + c_blanks;
                let prefix = format!(" |- {}", child_name);
                let child_str = format!(" {:<w$}{:>12}{:>13}{:>13}{:>13}{:>7}",
                    prefix,
                    format_num(child_reports.len(), &cli.num_format),
                    format_num(c_lines, &cli.num_format),
                    format_num(c_code, &cli.num_format),
                    format_num(c_comments, &cli.num_format),
                    format_num(c_blanks, &cli.num_format),
                    w = lang_col_w - 1
                );
                safe_println(&child_str);
            }

            let mut pt_code = lang.code;
            let mut pt_comments = lang.comments;
            let mut pt_blanks = lang.blanks;
            for child_reports in lang.children.values() {
                for r in child_reports {
                    pt_code += r.stats.code;
                    pt_comments += r.stats.comments;
                    pt_blanks += r.stats.blanks;
                }
            }
            let pt_lines = pt_code + pt_comments + pt_blanks;
            let total_child_str = format!(" {:<w$}{:>12}{:>13}{:>13}{:>13}{:>7}",
                " (Total)",
                "",
                format_num(pt_lines, &cli.num_format),
                format_num(pt_code, &cli.num_format),
                format_num(pt_comments, &cli.num_format),
                format_num(pt_blanks, &cli.num_format),
                w = lang_col_w - 1
            );
            safe_println(&total_child_str);
        }

        if cli.files {
            safe_println(&border_light);
            for report in &lang.reports {
                let r_lines = report.stats.code + report.stats.comments + report.stats.blanks;
                let file_str = format!(" {:<w$}{:>12}{:>13}{:>13}{:>13}{:>7}",
                    report.name.display(),
                    "",
                    format_num(r_lines, &cli.num_format),
                    format_num(report.stats.code, &cli.num_format),
                    format_num(report.stats.comments, &cli.num_format),
                    format_num(report.stats.blanks, &cli.num_format),
                    w = lang_col_w - 1
                );
                safe_println(&file_str);
            }
        }
    }

    safe_println(&border_heavy);

    let mut total_files = 0;
    let mut total_code = 0;
    let mut total_comments = 0;
    let mut total_blanks = 0;

    for (k, lang) in &languages_map {
        if type_set.as_ref().map_or(true, |ts| ts.contains(&k.to_lowercase())) {
            total_files += lang.reports.len();
            total_code += lang.code;
            total_comments += lang.comments;
            total_blanks += lang.blanks;

            for child_reports in lang.children.values() {
                for r in child_reports {
                    total_code += r.stats.code;
                    total_comments += r.stats.comments;
                    total_blanks += r.stats.blanks;
                }
            }
        }
    }

    let grand_lines = total_code + total_comments + total_blanks;

    let grand_str = format!(" {:<w$}{:>12}{:>13}{:>13}{:>13}{:>7}",
        "Total",
        format_num(total_files, &cli.num_format),
        format_num(grand_lines, &cli.num_format),
        format_num(total_code, &cli.num_format),
        format_num(total_comments, &cli.num_format),
        format_num(total_blanks, &cli.num_format),
        w = lang_col_w - 1
    );
    safe_println(&grand_str);

    safe_println(&border_heavy);
}

fn get_col_val(lang: &Language, col: &str) -> usize {
    match col {
        "files" => lang.reports.len(),
        "lines" => lang.code + lang.comments + lang.blanks,
        "code" => lang.code,
        "comments" => lang.comments,
        "blanks" => lang.blanks,
        _ => 0,
    }
}
EOF
"}

